import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"Error codes","description":"Union of client and admin OpenAPI Error.code plus console locales, excluding frontend NETWORK/HTTP/UNKNOWN.","frontmatter":{"title":"Error codes","description":"Union of client and admin OpenAPI Error.code plus console locales, excluding frontend NETWORK/HTTP/UNKNOWN."},"headers":[],"relativePath":"en/faq/errors.md","filePath":"en/faq/errors.md","lastUpdated":1790057721000}`),a={name:`en/faq/errors.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="error-codes" tabindex="-1">Error codes <a class="header-anchor" href="#error-codes" aria-label="Permalink to “Error codes”">​</a></h1><p>Branch on <code>error.code</code>. A wrong channel token is <strong>not</strong> 403. A missing store listing has <strong>no</strong> JSON <code>code</code>. Hover copy matches the docs-site <code>ErrorCode</code> component.</p><table tabindex="0"><thead><tr><th>code</th><th>HTTP (when stable)</th><th>Meaning</th></tr></thead><tbody><tr><td><code>PROJECT_NOT_FOUND</code></td><td>404</td><td>Project identity missed or alias expired</td></tr><tr><td><code>VERSION_NOT_FOUND</code></td><td>404</td><td>Version missing</td></tr><tr><td><code>VERSION_LINE_NOT_FOUND</code></td><td>404</td><td>No line for that os/arch</td></tr><tr><td><code>VERSION_NOT_VISIBLE</code></td><td>404/409</td><td>Version not visible to the client (draft, packs not ready, or gray miss)</td></tr><tr><td><code>VERSION_REVOKED</code></td><td>409</td><td>Revoked with no safe target</td></tr><tr><td><code>NO_SAFE_TARGET</code></td><td>409</td><td>No safe target</td></tr><tr><td><code>INTERMEDIATE_UNAVAILABLE</code></td><td>409</td><td>Min-source hop missing, not ready, cyclic, or more than 8 hops</td></tr><tr><td><code>MIN_OS_NOT_MET</code></td><td>409</td><td>OS/API below the current line floor</td></tr><tr><td><code>CHANNEL_CONFLICT</code></td><td>409</td><td>Idempotent create channel mismatch</td></tr><tr><td><code>UNAUTHORIZED</code></td><td>401</td><td>Missing/invalid credentials</td></tr><tr><td><code>FORBIDDEN</code></td><td>403</td><td>Insufficient permission (including project-only access to /admins, /geoip, /nodes)</td></tr><tr><td><code>PRECONDITION_FAILED</code></td><td>412</td><td>If-Match / ETag; not POST check</td></tr><tr><td><code>HW_REV_INCOMPATIBLE</code></td><td>409</td><td>hw_rev out of range</td></tr><tr><td><code>RATE_LIMITED</code></td><td>429</td><td>Too many requests; honor Retry-After</td></tr><tr><td><code>CHANGELOG_QUERY_INVALID</code></td><td>400</td><td>Illegal changelog query</td></tr><tr><td><code>NOT_FOUND</code></td><td>404</td><td>Generic missing resource</td></tr><tr><td><code>NOT_READY</code></td><td>503/400</td><td>Service or Passkey not ready. Either empty <code>webauthn_rp_id</code> or <code>webauthn_origins</code> makes Passkey routes return this code (HTTP 503)</td></tr><tr><td><code>INTERNAL_ERROR</code></td><td>500</td><td>Internal error</td></tr><tr><td><code>INVALID_REQUEST</code></td><td>400</td><td>Illegal body/fields (including non-.mmdb, caps, unknown matrix pair, duplicate listing)</td></tr><tr><td><code>INVALID_QUERY_PARAM</code></td><td>400</td><td>Illegal query (including announcement version and unknown changelog channel)</td></tr><tr><td><code>ENGINE_MISMATCH</code></td><td>400</td><td>Engine vs identity mismatch</td></tr><tr><td><code>ARTIFACT_REQUIRED</code></td><td>400</td><td>Publish rejected: no ready version line</td></tr><tr><td><code>CHANNEL_SUFFIX_MISMATCH</code></td><td>400</td><td>Prerelease suffix vs channel; stable cannot use a prerelease suffix</td></tr><tr><td><code>VERSION_ALREADY_EXISTS</code></td><td>409</td><td>Duplicate version in project</td></tr><tr><td><code>GRAY_NOT_ALLOWED_ON_CRITICAL</code></td><td>400</td><td>Gray on critical version</td></tr><tr><td><code>PACKAGE_TYPE_IMMUTABLE</code></td><td>409</td><td>package_type locked after a published line exists</td></tr><tr><td><code>COMPARE_ENGINE_IMMUTABLE</code></td><td>409</td><td>compare_engine locked after first publish</td></tr><tr><td><code>INVALID_PATH</code></td><td>400</td><td>Illegal path</td></tr><tr><td><code>ARTIFACT_IMMUTABLE</code></td><td>409</td><td>Published artifact immutable (yank the line first)</td></tr><tr><td><code>HW_REV_UNKNOWN</code></td><td>400</td><td>Unregistered hw_rev</td></tr><tr><td><code>DELTA_ALGO_UNSUPPORTED</code></td><td>400</td><td>Unknown delta algo</td></tr><tr><td><code>DELTA_SAME_VERSION</code></td><td>400</td><td>Delta source equals target</td></tr><tr><td><code>TOTP_RATE_LIMITED</code></td><td>429</td><td>TOTP attempts exhausted in one 30s period</td></tr><tr><td><code>UPLOAD_INCOMPLETE</code></td><td>400</td><td>Upload incomplete for this operation</td></tr><tr><td><code>CHANNEL_NOT_FOUND</code></td><td>404</td><td>Channel missing</td></tr><tr><td><code>SYSTEM_CHANNEL</code></td><td>409</td><td>System channels alpha/beta/stable cannot be deleted</td></tr><tr><td><code>CHECKSUM_MISMATCH</code></td><td>400</td><td>Declared SHA-256 mismatch</td></tr><tr><td><code>JOB_NOT_FOUND</code></td><td>404</td><td>Job missing</td></tr><tr><td><code>JOB_FAILED</code></td><td>409/500</td><td>Async job failed</td></tr><tr><td><code>AUTO_PUBLISH_PENDING</code></td><td>409</td><td>auto_publish_when is not fully ready yet</td></tr><tr><td><code>ZIP_LAYOUT_INVALID</code></td><td>400</td><td>Zip layout is not os/arch/… (missing segments, unknown ids or traversal)</td></tr><tr><td><code>ADMIN_NOT_FOUND</code></td><td>404</td><td>Admin missing</td></tr><tr><td><code>USERNAME_TAKEN</code></td><td>409</td><td>Username taken</td></tr><tr><td><code>LAST_ADMIN</code></td><td>409</td><td>Cannot delete last admin</td></tr><tr><td><code>LAST_OWNER</code></td><td>400</td><td>Cannot remove last owner</td></tr><tr><td><code>MEMBER_NOT_FOUND</code></td><td>404</td><td>Member missing</td></tr><tr><td><code>CLIENT_NOT_FOUND</code></td><td>404</td><td>Roster client missing</td></tr><tr><td><code>GEOIP_NOT_FOUND</code></td><td>404</td><td>GeoIP database missing</td></tr><tr><td><code>LANGUAGE_TAKEN</code></td><td>409</td><td>Language code taken</td></tr><tr><td><code>LANGUAGE_NOT_FOUND</code></td><td>404</td><td>Language missing</td></tr></tbody></table><p><code>DELTA_SAME_VERSION</code> comes from console locales and is not in the admin OpenAPI <code>Error.code</code> enum; treat it as “source equals target”. Excluded frontend-only <code>NETWORK_ERROR</code> / <code>HTTP_ERROR</code> / <code>UNKNOWN_ERROR</code>. Missing store listings have <strong>no</strong> JSON <code>code</code>.</p>`,4)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};